import{_ as a}from"./chunks/11b-settings-add-root.Dcjj_7UM.js";import{_ as o}from"./chunks/09-login.Cp0oUy7l.js";import{_ as t,o as i,c as r,a2 as n}from"./chunks/framework.DUZafPzB.js";const b=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"ops/faq.md","filePath":"ops/faq.md","lastUpdated":1791422495000}'),s={name:"ops/faq.md"};function l(d,e,c,h,f,u){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="no-agent-in-the-sidebar" tabindex="-1">No Agent in the sidebar? <a class="header-anchor" href="#no-agent-in-the-sidebar" aria-label="Permalink to &quot;No Agent in the sidebar?&quot;">​</a></h2><p>Check in order:</p><ol><li>Is the Agent process running (<code>ps</code> / systemd status)?</li><li>Can the Agent resolve the Hub hostname: on the Agent host <code>curl -v https://filebox.example.com/api/health</code>.</li><li>Is the Hub URL <code>https://</code> (or for dev, explicit <code>FILEBOX_ALLOW_INSECURE_HUB=1</code> + <code>ws://</code>)?</li><li>Does the token match what Hub <code>--init-config</code> printed (Hub stores only a hash — mismatch means re-issue / reconfigure)?</li><li>Does the reverse proxy upgrade WebSockets (<code>Upgrade</code> / <code>Connection</code>)? See <a href="./hub">Hub ops</a>.</li></ol><h2 id="agent-online-but-empty-file-list" tabindex="-1">Agent online but empty file list? <a class="header-anchor" href="#agent-online-but-empty-file-list" aria-label="Permalink to &quot;Agent online but empty file list?&quot;">​</a></h2><p>Add a readable directory under <strong>Settings → Add Root</strong>. Invalid paths are rejected without harming existing config. See <a href="/filebox/guide/first-login">First login</a>.</p><p><img src="'+a+'" alt="Add Root"></p><h2 id="login-stuck-on-solving-continue-disabled" tabindex="-1">Login stuck on Solving / Continue disabled? <a class="header-anchor" href="#login-stuck-on-solving-continue-disabled" aria-label="Permalink to &quot;Login stuck on Solving / Continue disabled?&quot;">​</a></h2><p>PoW must finish first (Verification → Ready). If stuck: refresh the challenge, check <code>/api/pow/challenge</code> reachability, and whether IP rate limiting kicked in. See <a href="/filebox/guide/first-login">First login</a>.</p><p><img src="'+o+'" alt="Login PoW"></p><h2 id="search-slow-cancelled" tabindex="-1">Search slow / cancelled? <a class="header-anchor" href="#search-slow-cancelled" aria-label="Permalink to &quot;Search slow / cancelled?&quot;">​</a></h2><p>For large trees, narrow the root, deepen ignore lists (<code>node_modules</code> / <code>venv</code>), lower depth; Cancel anytime. One search at a time per Agent. See <a href="/filebox/features/search">Search</a>.</p><h2 id="some-files-won-t-open" tabindex="-1">Some files won’t open? <a class="header-anchor" href="#some-files-won-t-open" aria-label="Permalink to &quot;Some files won’t open?&quot;">​</a></h2><p>Sensitive paths (<code>.ssh/</code>, <code>.env*</code>, <code>*.pem</code>, …) are denied by default even inside authorized roots. See <a href="/filebox/features/security">Security &amp; sensitive files</a>.</p><h2 id="office-preview-greyed-out-failing" tabindex="-1">Office preview greyed out / failing? <a class="header-anchor" href="#office-preview-greyed-out-failing" aria-label="Permalink to &quot;Office preview greyed out / failing?&quot;">​</a></h2><p>Is a usable <code>soffice</code> configured on the Agent? See <a href="./office">Office preview</a>. Without LibreOffice you can still Download.</p><h2 id="terminal-asks-for-a-code" tabindex="-1">Terminal asks for a code? <a class="header-anchor" href="#terminal-asks-for-a-code" aria-label="Permalink to &quot;Terminal asks for a code?&quot;">​</a></h2><p>Complete <code>./agent --setup-terminal-2fa</code> on the Agent host (or set <code>FILEBOX_AGENT_TERMINAL_TOTP_SECRET</code>) and restart. The Hub never stores the secret. Every Open / Resume needs a fresh code. See <a href="/filebox/features/terminal">Terminal</a>.</p><h2 id="no-transfer-entry" tabindex="-1">No Transfer entry? <a class="header-anchor" href="#no-transfer-entry" aria-label="Permalink to &quot;No Transfer entry?&quot;">​</a></h2><p>Transfer appears only when the Agent advertises <code>temp_upload</code>. Current releases have it by default; custom builds that disable the capability will hide it.</p><h2 id="is-there-a-live-demo-are-the-screenshots-real" tabindex="-1">Is there a live demo? Are the screenshots real? <a class="header-anchor" href="#is-there-a-live-demo-are-the-screenshots-real" aria-label="Permalink to &quot;Is there a live demo? Are the screenshots real?&quot;">​</a></h2><p>There is no hosted live demo — filebox needs your own Hub and Agent to browse real files; the <a href="/filebox/guide/quick-start">Quick start</a> gets one running locally in minutes. <strong>Every screenshot on this site comes from a live Hub + Agent</strong> — the same UI you get after deploying (login PoW, multi-tab preview, Search float, Settings, Audit, Terminal TOTP, …).</p><h2 id="local-debugging" tabindex="-1">Local debugging? <a class="header-anchor" href="#local-debugging" aria-label="Permalink to &quot;Local debugging?&quot;">​</a></h2><p>See <a href="https://github.com/ZhimingYe/filebox/blob/main/docs/local-debugging.md" target="_blank" rel="noreferrer"><code>docs/local-debugging.md</code></a> in the repo (<code>FILEBOX_DEV_MODE=1</code>, etc.). Repo-root <code>docs/</code> is developer runbooks and is <strong>not</strong> part of this user docs site.</p>',24)])])}const _=t(s,[["render",l]]);export{b as __pageData,_ as default};
